"use client";

import { useEffect, useState } from "react";
import ConfirmDeleteModal from "./ConfirmDeleteModal";
import CreateLeagueModal from "./CreateLeagueModal";
import { getUserLeagues, deleteLeague } from "../lib/api";

export default function Home() {
  const [leagues, setLeagues] = useState([]);
  const [deleteTarget, setDeleteTarget] = useState(null);
  const [isCreateOpen, setIsCreateOpen] = useState(false);

  const DEFAULT_LOGO = "https://i.imgur.com/DxHxkuJ.png";

  useEffect(() => {
    async function loadLeagues() {
      const userId = localStorage.getItem("user_id");

      if (!userId) {
        console.log("No user_id found, skipping league fetch");
        setLeagues([]);
        return;
      }

      try {
        const response = await getUserLeagues(userId);
        setLeagues(response.data);
      } catch (error) {
        console.error("Error loading leagues:", error);
      }
    }

    loadLeagues();
  }, []);

  const onCreateLeague = () => {
    setIsCreateOpen(true);
  };

  return (
    <div className="home">
      <div className="home-header">
        <h1 className="home-leagues-title">Leagues</h1>
        <div className="tooltip-wrap tooltip-right" data-tip="Create a new league">
          <button className="create-league-btn" onClick={onCreateLeague}>
            +
          </button>
        </div>
      </div>

      {leagues.length === 0 ? (
        <div className="home-empty">
          <h2>No leagues yet.</h2>
          <p>Click the button to create one.</p>
        </div>
      ) : (
        <div className="league-grid">
          {leagues.map((league) => (
            <div className="league-card" key={league.id}>
              <button
                className="league-close"
                type="button"
                onClick={(e) => {
                  e.stopPropagation();
                  setDeleteTarget({
                    id: league.id,
                    name: league.title || league.name,
                  });
                }}
                aria-label="Remove league"
              >
                ×
              </button>

              <img
                className="league-logo-placeholder"
                src={
                  league.leagueIconUrl ||
                  league.league_icon_url ||
                  league.logoUrl ||
                  DEFAULT_LOGO
                }
                alt="league logo"
              />

              <div className="league-title">{league.title || league.name}</div>

              <div className="league-subtitle">
                {league.format} • {league.teamCount ?? 0} TEAMS • {league.season} SEASON
              </div>

              <div className="league-season">Season {league.seasonNum}</div>
            </div>
          ))}
        </div>
      )}

      <ConfirmDeleteModal
        isOpen={!!deleteTarget}
        leagueName={deleteTarget?.name || ""}
        onCancel={() => setDeleteTarget(null)}
        onConfirm={async () => {
          try {
            await deleteLeague(deleteTarget.id);
            setLeagues((prev) =>
              prev.filter((l) => l.id !== deleteTarget.id)
            );
            setDeleteTarget(null);
          } catch (err) {
            console.error("Failed to delete league:", err);
            alert("Error deleting league. Please try again.");
          }
        }}
      />

      <CreateLeagueModal
        isOpen={isCreateOpen}
        onClose={() => setIsCreateOpen(false)}
        onSave={(newLeague) => {
          console.log("new league from modal:", newLeague);
          setLeagues((prev) => [newLeague, ...prev]);
          setIsCreateOpen(false);
        }}
      />
    </div>
  );
}